{
  "items": [
    {
      "name": "NNReal.eventually_pow_one_div_le",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Continuity",
      "kind": "theorem",
      "type": "∀ (x : NNReal) {y : NNReal}, 1 < y → ∀ᶠ (n : ℕ) in Filter.atTop, x ^ (1 / ↑n) ≤ y"
    },
    {
      "name": "Asymptotics.isLittleO_pow_pow_atTop_of_lt",
      "module_name": "Mathlib.Analysis.Asymptotics.SpecificAsymptotics",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} [inst : NormedField 𝕜] [inst_1 : LinearOrder 𝕜] [IsStrictOrderedRing 𝕜] [OrderTopology 𝕜] {p q : ℕ},\n  p < q → (fun x => x ^ p) =o[Filter.atTop] fun x => x ^ q"
    },
    {
      "name": "tendsto_pow_const_div_const_pow_of_one_lt",
      "module_name": "Mathlib.Analysis.SpecificLimits.Normed",
      "kind": "theorem",
      "type": "∀ (k : ℕ) {r : ℝ}, 1 < r → Filter.Tendsto (fun n => ↑n ^ k / r ^ n) Filter.atTop (nhds 0)"
    },
    {
      "name": "PadicInt.exists_pow_neg_lt",
      "module_name": "Mathlib.NumberTheory.Padics.PadicIntegers",
      "kind": "theorem",
      "type": "∀ (p : ℕ) [hp : Fact (Nat.Prime p)] {ε : ℝ}, 0 < ε → ∃ k, ↑p ^ (-↑k) < ε"
    },
    {
      "name": "ENNReal.eventually_pow_one_div_le",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Continuity",
      "kind": "theorem",
      "type": "∀ {x : ENNReal}, x ≠ ⊤ → ∀ {y : ENNReal}, 1 < y → ∀ᶠ (n : ℕ) in Filter.atTop, x ^ (1 / ↑n) ≤ y"
    },
    {
      "name": "LiouvilleWith.frequently_lt_rpow_neg",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ {p q x : ℝ}, LiouvilleWith p x → q < p → ∃ᶠ (n : ℕ) in Filter.atTop, ∃ m, x ≠ ↑m / ↑n ∧ |x - ↑m / ↑n| < ↑n ^ (-q)"
    },
    {
      "name": "padicValRat.pow",
      "module_name": "Mathlib.NumberTheory.Padics.PadicVal.Basic",
      "kind": "theorem",
      "type": "∀ {p : ℕ} [hp : Fact (Nat.Prime p)] {q : ℚ}, q ≠ 0 → ∀ {k : ℕ}, padicValRat p (q ^ k) = ↑k * padicValRat p q"
    },
    {
      "name": "Nat.factors_lemma",
      "module_name": "Mathlib.Data.Nat.Prime.Defs",
      "kind": "theorem",
      "type": "∀ {k : ℕ}, (k + 2) / (k + 2).minFac < k + 2"
    }
  ]
}
